159:                                                     unresolvedCall,
160:                                                     newInference,
161:                                                     resolvedArgs,
162:                                                     surroundingInfo))
163:                             .orElseThrow(
164:                                     () ->
165:                                             new TableException(
166:                                                     "Could not get a type inference for function: "
167:                                                             + functionName)));
