293:         if (ns instanceof IdentifierNamespace) {
294:             SqlNode enclosingNode = ns.getEnclosingNode();
295:             // FOR SYSTEM_TIME AS OF [expression]
296:             if (enclosingNode instanceof SqlSnapshot) {
