353:     @Override
354:     protected @PolyNull SqlNode performUnconditionalRewrites(
355:             @PolyNull SqlNode node, boolean underFrom) {
356: 
357:         // Special case for window TVFs like:
358:         // TUMBLE(TABLE t, DESCRIPTOR(metadata_virtual), INTERVAL '1' MINUTE))
359:         //
360:         // "TABLE t" is translated into an implicit "SELECT * FROM t". This would ignore columns
361:         // that are not expanded by default. However, the descriptor explicitly states the need
362:         // for this column. Therefore, explicit table expressions (for window TVFs at most one)
363:         // are captured before rewriting and replaced with a "marker" SqlSelect that contains the
364:         // descriptor information. The "marker" SqlSelect is considered during column expansion.
365:         final List<SqlIdentifier> explicitTableArgs = getExplicitTableOperands(node);
366: 
367:         final SqlNode rewritten = super.performUnconditionalRewrites(node, underFrom);
368: 
369:         if (!(node instanceof SqlBasicCall)) {
370:             return rewritten;
371:         }
372:         final SqlBasicCall call = (SqlBasicCall) node;
373:         final SqlOperator operator = call.getOperator();
374: 
375:         if (operator instanceof SqlWindowTableFunction) {
376:             if (explicitTableArgs.stream().allMatch(Objects::isNull)) {
377:                 return rewritten;
378:             }
379: 
380:             final List<SqlIdentifier> descriptors =
381:                     call.getOperandList().stream()
382:                             .flatMap(FlinkCalciteSqlValidator::extractDescriptors)
383:                             .collect(Collectors.toList());
384: 
385:             for (int i = 0; i < call.operandCount(); i++) {
386:                 final SqlIdentifier tableArg = explicitTableArgs.get(i);
387:                 if (tableArg != null) {
388:                     final SqlNode opReplacement = new ExplicitTableSqlSelect(tableArg, descriptors);
389:                     if (call.operand(i).getKind() == SqlKind.ARGUMENT_ASSIGNMENT) {
390:                         // for TUMBLE(DATA => TABLE t3, ...)
391:                         final SqlCall assignment = call.operand(i);
392:                         assignment.setOperand(0, opReplacement);
393:                     } else {
394:                         // for TUMBLE(TABLE t3, ...)
395:                         call.setOperand(i, opReplacement);
396:                     }
397:                 }
398:                 // for TUMBLE([DATA =>] SELECT ..., ...)
399:             }
400:         }
401: 
402:         return rewritten;
403:     }
