409:     /**
410:      * A special {@link SqlSelect} to capture the origin of a {@link SqlKind#EXPLICIT_TABLE} within
411:      * TVF operands.
412:      */
413:     private static class ExplicitTableSqlSelect extends SqlSelect {
414: 
415:         private final List<SqlIdentifier> descriptors;
416: 
417:         public ExplicitTableSqlSelect(SqlIdentifier table, List<SqlIdentifier> descriptors) {
418:             super(
419:                     SqlParserPos.ZERO,
420:                     null,
421:                     SqlNodeList.of(SqlIdentifier.star(SqlParserPos.ZERO)),
422:                     table,
423:                     null,
424:                     null,
425:                     null,
426:                     null,
427:                     null,
428:                     null,
429:                     null,
430:                     null);
431:             this.descriptors = descriptors;
432:         }
433:     }
434: 
435:     /**
436:      * Returns whether the given column has been declared in a {@link SqlKind#DESCRIPTOR} next to a
437:      * {@link SqlKind#EXPLICIT_TABLE} within TVF operands.
438:      */
439:     private static boolean declaredDescriptorColumn(SelectScope scope, Column column) {
440:         if (!(scope.getNode() instanceof ExplicitTableSqlSelect)) {
441:             return false;
442:         }
443:         final ExplicitTableSqlSelect select = (ExplicitTableSqlSelect) scope.getNode();
444:         return select.descriptors.stream()
445:                 .map(SqlIdentifier::getSimple)
446:                 .anyMatch(id -> id.equals(column.getName()));
447:     }
448: 
449:     /**
450:      * Returns all {@link SqlKind#EXPLICIT_TABLE} operands within TVF operands. A list entry is
451:      * {@code null} if the operand is not an {@link SqlKind#EXPLICIT_TABLE}.
452:      */
453:     private static List<SqlIdentifier> getExplicitTableOperands(SqlNode node) {
454:         if (!(node instanceof SqlBasicCall)) {
455:             return null;
456:         }
457:         final SqlBasicCall call = (SqlBasicCall) node;
458: 
459:         if (!(call.getOperator() instanceof SqlFunction)) {
460:             return null;
461:         }
462:         final SqlFunction function = (SqlFunction) call.getOperator();
463: 
464:         if (!isTableFunction(function)) {
465:             return null;
466:         }
467: 
468:         return call.getOperandList().stream()
469:                 .map(FlinkCalciteSqlValidator::extractExplicitTable)
470:                 .collect(Collectors.toList());
471:     }
472: 
473:     private static @Nullable SqlIdentifier extractExplicitTable(SqlNode op) {
474:         if (op.getKind() == SqlKind.EXPLICIT_TABLE) {
475:             final SqlBasicCall opCall = (SqlBasicCall) op;
476:             if (opCall.operandCount() == 1 && opCall.operand(0) instanceof SqlIdentifier) {
477:                 // for TUMBLE(TABLE t3, ...)
478:                 return opCall.operand(0);
479:             }
480:         } else if (op.getKind() == SqlKind.ARGUMENT_ASSIGNMENT) {
481:             // for TUMBLE(DATA => TABLE t3, ...)
482:             final SqlBasicCall opCall = (SqlBasicCall) op;
483:             return extractExplicitTable(opCall.operand(0));
484:         }
485:         return null;
486:     }
487: 
488:     private static Stream<SqlIdentifier> extractDescriptors(SqlNode op) {
489:         if (op.getKind() == SqlKind.DESCRIPTOR) {
490:             // for TUMBLE(..., DESCRIPTOR(col), ...)
491:             final SqlBasicCall opCall = (SqlBasicCall) op;
492:             return opCall.getOperandList().stream()
493:                     .filter(SqlIdentifier.class::isInstance)
494:                     .map(SqlIdentifier.class::cast);
495:         } else if (op.getKind() == SqlKind.ARGUMENT_ASSIGNMENT) {
496:             // for TUMBLE(..., TIMECOL => DESCRIPTOR(col), ...)
497:             final SqlBasicCall opCall = (SqlBasicCall) op;
498:             return extractDescriptors(opCall.operand(0));
499:         }
500:         return Stream.empty();
501:     }
502: 
503:     private static boolean isTableFunction(SqlFunction function) {
504:         return function instanceof SqlTableFunction
505:                 || function.getFunctionType() == SqlFunctionCategory.USER_DEFINED_TABLE_FUNCTION;
506:     }
507: }
