1401:     private CompletableFuture<ExecutionGraph> createExecutionGraphAndRestoreStateAsync(
1402:             VertexParallelismStore adjustedParallelismStore) {
1403:         backgroundTask.abort();
1404: 
1405:         backgroundTask =
