298:         private final Duration initialResourceAllocationTimeout;
299:         private final Duration resourceStabilizationTimeout;
300:         private final Duration slotIdleTimeout;
301:         private final Duration executingCooldownTimeout;
302:         private final Duration scalingResourceStabilizationTimeout;
303:         private final Duration maximumDelayForTriggeringRescale;
304:         private final int rescaleOnFailedCheckpointCount;
