457:             int numExpectedBuffers, int minUsedBuffers, int maxUsedBuffers) throws IOException {
458:         return internalCreateBufferPool(
459:                 numExpectedBuffers, minUsedBuffers, maxUsedBuffers, 0, Integer.MAX_VALUE, 0);
