755:         return String.format(
756:                 "The total number of network buffers is currently set to %d of %d bytes each. "
757:                         + "You can increase this number by setting the configuration keys '%s', '%s', and '%s'",
758:                 totalNumberOfMemorySegments,
759:                 memorySegmentSize,
760:                 TaskManagerOptions.NETWORK_MEMORY_FRACTION.key(),
761:                 TaskManagerOptions.NETWORK_MEMORY_MIN.key(),
762:                 TaskManagerOptions.NETWORK_MEMORY_MAX.key());
