276:     @Nullable
277:     private MemorySegment internalRequestMemorySegment() {
278:         assert Thread.holdsLock(availableMemorySegments);
279: 
280:         final MemorySegment segment = availableMemorySegments.poll();
281:         if (availableMemorySegments.isEmpty() && segment != null) {
282:             availabilityHelper.resetUnavailable();
283:         }
284:         return segment;
285:     }
