287:     /**
288:      * Corresponding to {@link #requestUnpooledMemorySegments}, this method is for unpooled memory
289:      * segments recycling.
290:      */
291:     @Override
292:     public void recycleUnpooledMemorySegments(Collection<MemorySegment> segments) {
293:         internalRecycleMemorySegments(segments);
294:         revertRequiredBuffers(segments.size());
