456:     public BufferPool createBufferPool(
457:             int requiredFloatingBuffers, int minUsedBuffers, int maxUsedBuffers) throws IOException {
458:         return internalCreateBufferPool(
459:                 requiredFloatingBuffers, minUsedBuffers, maxUsedBuffers, 0, Integer.MAX_VALUE, 0);
