228:     /**
229:      * Closes the catalog manager and releases its resources.
230:      *
231:      * <p>This method closes all initialized catalogs and the catalog store.
232:      *
233:      * @throws CatalogException if an error occurs while closing the catalogs or the catalog store
234:      */
235:     public void close() throws CatalogException {
236:         // close the initialized catalogs
237:         List<Throwable> errors = new ArrayList<>();
238:         for (Map.Entry<String, Catalog> entry : catalogs.entrySet()) {
239:             String catalogName = entry.getKey();
240:             Catalog catalog = entry.getValue();
241:             try {
242:                 catalog.close();
243:             } catch (Throwable e) {
244:                 LOG.error(
245:                         String.format(
246:                                 "Failed to close catalog %s: %s", catalogName, e.getMessage()),
247:                         e);
248:                 errors.add(e);
249:             }
250:         }
251: 
252:         // close the catalog store holder
253:         try {
254:             catalogStoreHolder.close();
255:         } catch (Throwable e) {
256:             errors.add(e);
257:             LOG.error(String.format("Failed to close catalog store holder: %s", e.getMessage()), e);
258:         }
259: 
260:         if (!errors.isEmpty()) {
261:             CatalogException exception = new CatalogException("Failed to close catalog manager");
262:             for (Throwable e : errors) {
263:                 exception.addSuppressed(e);
264:             }
265:             throw exception;
266:         }
267:     }
