293:     /**
294:      * Creates a catalog under the given name. The catalog name must be unique.
295:      *
296:      * @param catalogName the given catalog name under which to create the given catalog
297:      * @param catalogDescriptor catalog descriptor for creating catalog
298:      * @param ignoreIfExists if false exception will be thrown if a catalog exists.
299:      * @throws CatalogException If the catalog already exists in the catalog store or initialized
300:      *     catalogs, or if an error occurs while creating the catalog or storing the {@link
301:      *     CatalogDescriptor}
302:      */
303:     public void createCatalog(
304:             String catalogName, CatalogDescriptor catalogDescriptor, boolean ignoreIfExists)
305:             throws CatalogException {
306:         checkArgument(
307:                 !StringUtils.isNullOrWhitespaceOnly(catalogName),
308:                 "Catalog name cannot be null or empty.");
309:         checkNotNull(catalogDescriptor, "Catalog descriptor cannot be null");
310: 
311:         boolean catalogExistsInStore = catalogStoreHolder.catalogStore().contains(catalogName);
312:         boolean catalogExistsInMemory = catalogs.containsKey(catalogName);
313: 
314:         if (catalogExistsInStore || catalogExistsInMemory) {
315:             if (!ignoreIfExists) {
316:                 throw new CatalogException(format("Catalog %s already exists.", catalogName));
317:             }
318:         } else {
319:             // Store the catalog in the catalog store
320:             catalogStoreHolder.catalogStore().storeCatalog(catalogName, catalogDescriptor);
321: 
322:             // Initialize and store the catalog in memory
323:             Catalog catalog = initCatalog(catalogName, catalogDescriptor);
324:             catalog.open();
325:             catalogs.put(catalogName, catalog);
326:         }
327:     }
