333:     /**
334:      * Alters a catalog under the given name. The catalog name must be unique.
335:      *
336:      * @param catalogName the given catalog name under which to alter the given catalog
337:      * @param catalogUpdater catalog configuration updater to alter catalog
338:      * @throws CatalogException If the catalog neither exists in the catalog store nor in the
339:      *     initialized catalogs, or if an error occurs while creating the catalog or storing the
340:      *     {@link CatalogDescriptor}
341:      */
342:     public void alterCatalog(String catalogName, Consumer<Configuration> catalogUpdater)
343:             throws CatalogException {
344:         checkArgument(
345:                 !StringUtils.isNullOrWhitespaceOnly(catalogName),
346:                 "Catalog name cannot be null or empty.");
347:         checkNotNull(catalogUpdater, "Catalog configuration updater cannot be null.");
348: 
349:         CatalogStore catalogStore = catalogStoreHolder.catalogStore();
350:         Optional<CatalogDescriptor> oldCatalogDescriptor = getCatalogDescriptor(catalogName);
351: 
352:         if (catalogStore.contains(catalogName) && oldCatalogDescriptor.isPresent()) {
353:             Configuration conf = oldCatalogDescriptor.get().getConfiguration();
354:             catalogUpdater.accept(conf);
355:             CatalogDescriptor newCatalogDescriptor = CatalogDescriptor.of(catalogName, conf);
356:             Catalog newCatalog = initCatalog(catalogName, newCatalogDescriptor);
357:             catalogStore.removeCatalog(catalogName, false);
358:             if (catalogs.containsKey(catalogName)) {
359:                 catalogs.get(catalogName).close();
360:             }
361:             newCatalog.open();
362:             catalogs.put(catalogName, newCatalog);
363:             catalogStoreHolder.catalogStore().storeCatalog(catalogName, newCatalogDescriptor);
364:         } else {
365:             throw new CatalogException(
366:                     String.format("Catalog %s does not exist in the catalog store.", catalogName));
367:         }
368:     }
