370:     private Catalog initCatalog(String catalogName, CatalogDescriptor catalogDescriptor) {
371:         return FactoryUtil.createCatalog(
372:                 catalogName,
373:                 catalogDescriptor.getConfiguration().toMap(),
374:                 catalogStoreHolder.config(),
375:                 catalogStoreHolder.classLoader());
