445:      * @param catalogName name of the catalog to retrieve
446:      * @return the requested catalog or empty if it does not exist
447:      */
448:     public Optional<Catalog> getCatalog(String catalogName) {
449:         // Get catalog from the initialized catalogs.
450:         if (catalogs.containsKey(catalogName)) {
451:             return Optional.of(catalogs.get(catalogName));
452:         }
