454:         // Get catalog from the CatalogStore.
455:         Optional<CatalogDescriptor> optionalDescriptor = getCatalogDescriptor(catalogName);
456:         return optionalDescriptor.map(
457:                 descriptor -> {
458:                     Catalog catalog = initCatalog(catalogName, descriptor);
459:                     catalog.open();
460:                     catalogs.put(catalogName, catalog);
461:                     return catalog;
462:                 });
