704:     private Optional<ContextResolvedTable> getPermanentTable(
705:             ObjectIdentifier objectIdentifier, @Nullable Long timestamp) {
706:         Optional<Catalog> catalogOptional = getCatalog(objectIdentifier.getCatalogName());
707:         ObjectPath objectPath = objectIdentifier.toObjectPath();
708:         if (catalogOptional.isPresent()) {
709:             Catalog currentCatalog = catalogOptional.get();
710:             try {
711:                 final CatalogBaseTable table;
712:                 if (timestamp != null) {
713:                     table = currentCatalog.getTable(objectPath, timestamp);
714:                     if (table.getTableKind() == CatalogBaseTable.TableKind.VIEW) {
715:                         throw new TableException(
716:                                 String.format(
717:                                         "%s is a view, but time travel is not supported for view.",
718:                                         objectIdentifier.asSummaryString()));
719:                     }
720:                 } else {
721:                     table = currentCatalog.getTable(objectPath);
722:                 }
723:                 final ResolvedCatalogBaseTable<?> resolvedTable = resolveCatalogBaseTable(table);
724:                 return Optional.of(
725:                         ContextResolvedTable.permanent(
726:                                 objectIdentifier, currentCatalog, resolvedTable));
727:             } catch (TableNotExistException e) {
728:                 // Ignore.
729:             }
730:         }
731:         return Optional.empty();
732:     }
