734:     private Optional<CatalogBaseTable> getUnresolvedTable(ObjectIdentifier objectIdentifier) {
735:         Optional<Catalog> currentCatalog = getCatalog(objectIdentifier.getCatalogName());
736:         ObjectPath objectPath = objectIdentifier.toObjectPath();
737:         if (currentCatalog.isPresent()) {
738:             try {
739:                 final CatalogBaseTable table = currentCatalog.get().getTable(objectPath);
740:                 return Optional.of(table);
741:             } catch (TableNotExistException e) {
742:                 // Ignore.
743:             }
744:         }
745:         return Optional.empty();
746:     }
