1037:      * @param ignoreIfExists if false exception will be thrown if a table exists in the given path.
1038:      */
1039:     public void createTemporaryTable(
1040:             CatalogBaseTable table, ObjectIdentifier objectIdentifier, boolean ignoreIfExists) {
1041:         Optional<TemporaryOperationListener> listener =
1042:                 getTemporaryOperationListener(objectIdentifier);
1043:         temporaryTables.compute(
1044:                 objectIdentifier,
1045:                 (k, v) -> {
1046:                     if (v != null) {
1047:                         if (!ignoreIfExists) {
1048:                             throw new ValidationException(
1049:                                     String.format(
1050:                                             "Temporary table '%s' already exists",
1051:                                             objectIdentifier));
1052:                         }
1053:                         return v;
1054:                     } else {
1055:                         ResolvedCatalogBaseTable<?> resolvedTable = resolveCatalogBaseTable(table);
1056:                         Catalog catalog =
1057:                                 getCatalog(objectIdentifier.getCatalogName()).orElse(null);
1058:                         ResolvedCatalogBaseTable<?> resolvedListenedTable =
1059:                                 managedTableListener.notifyTableCreation(
1060:                                         catalog,
1061:                                         objectIdentifier,
1062:                                         resolvedTable,
1063:                                         true,
1064:                                         ignoreIfExists);
1065: 
1066:                         if (listener.isPresent()) {
1067:                             return listener.get()
1068:                                     .onCreateTemporaryTable(
1069:                                             objectIdentifier.toObjectPath(), resolvedListenedTable);
1070:                         }
1071:                         if (resolvedListenedTable instanceof CatalogTable) {
1072:                             catalogModificationListeners.forEach(
1073:                                     l ->
1074:                                             l.onEvent(
1075:                                                     CreateTableEvent.createEvent(
1076:                                                             CatalogContext.createContext(
1077:                                                                     objectIdentifier
1078:                                                                             .getCatalogName(),
1079:                                                                     catalog),
1080:                                                             objectIdentifier,
1081:                                                             resolvedListenedTable,
1082:                                                             ignoreIfExists,
1083:                                                             true)));
1084:                         }
1085:                         return resolvedListenedTable;
1086:                     }
1087:                 });
1088:     }
