1140:     private void dropTemporaryTableInternal(
1141:             ObjectIdentifier objectIdentifier,
1142:             Predicate<CatalogBaseTable> filter,
1143:             boolean ignoreIfNotExists,
1144:             boolean isDropTable) {
1145:         CatalogBaseTable catalogBaseTable = temporaryTables.get(objectIdentifier);
1146:         if (filter.test(catalogBaseTable)) {
1147:             getTemporaryOperationListener(objectIdentifier)
1148:                     .ifPresent(l -> l.onDropTemporaryTable(objectIdentifier.toObjectPath()));
1149: 
1150:             Catalog catalog = getCatalog(objectIdentifier.getCatalogName()).orElse(null);
1151:             ResolvedCatalogBaseTable<?> resolvedTable = resolveCatalogBaseTable(catalogBaseTable);
1152:             managedTableListener.notifyTableDrop(
1153:                     catalog, objectIdentifier, resolvedTable, true, ignoreIfNotExists);
1154: 
1155:             temporaryTables.remove(objectIdentifier);
1156:             if (isDropTable) {
1157:                 catalogModificationListeners.forEach(
1158:                         listener ->
1159:                                 listener.onEvent(
1160:                                         DropTableEvent.createEvent(
1161:                                                 CatalogContext.createContext(
1162:                                                         objectIdentifier.getCatalogName(), catalog),
1163:                                                 objectIdentifier,
1164:                                                 resolvedTable,
1165:                                                 ignoreIfNotExists,
1166:                                                 true)));
1167:             }
1168:         } else if (!ignoreIfNotExists) {
1169:             throw new ValidationException(
1170:                     String.format(
1171:                             "Temporary table or view with identifier '%s' does not exist.",
1172:                             objectIdentifier.asSummaryString()));
1173:         }
1174:     }
