1176:     protected Optional<TemporaryOperationListener> getTemporaryOperationListener(
1177:             ObjectIdentifier identifier) {
1178:         return getCatalog(identifier.getCatalogName())
1179:                 .map(
1180:                         c ->
1181:                                 c instanceof TemporaryOperationListener
1182:                                         ? (TemporaryOperationListener) c
1183:                                         : null);
1184:     }
