1277:     private void dropTableInternal(
1278:             ObjectIdentifier objectIdentifier, boolean ignoreIfNotExists, boolean isDropTable) {
1279:         Predicate<CatalogBaseTable> filter =
1280:                 isDropTable
1281:                         ? table ->
1282:                                 table instanceof CatalogTable
1283:                                         || table instanceof CatalogMaterializedTable
1284:                         : table -> table instanceof CatalogView;
1285:         // Same name temporary table or view exists.
1286:         if (filter.test(temporaryTables.get(objectIdentifier))) {
1287:             String tableOrView = isDropTable ? "table" : "view";
1288:             throw new ValidationException(
1289:                     String.format(
1290:                             "Temporary %s with identifier '%s' exists. "
1291:                                     + "Drop it first before removing the permanent %s.",
1292:                             tableOrView, objectIdentifier, tableOrView));
1293:         }
1294:         final Optional<CatalogBaseTable> resultOpt = getUnresolvedTable(objectIdentifier);
1295:         if (resultOpt.isPresent() && filter.test(resultOpt.get())) {
1296:             execute(
1297:                     (catalog, path) -> {
1298:                         ResolvedCatalogBaseTable<?> resolvedTable =
1299:                                 resolveCatalogBaseTable(resultOpt.get());
1300:                         managedTableListener.notifyTableDrop(
1301:                                 catalog, objectIdentifier, resolvedTable, false, ignoreIfNotExists);
1302: 
1303:                         catalog.dropTable(path, ignoreIfNotExists);
1304:                         if (isDropTable) {
1305:                             catalogModificationListeners.forEach(
1306:                                     listener ->
1307:                                             listener.onEvent(
1308:                                                     DropTableEvent.createEvent(
1309:                                                             CatalogContext.createContext(
1310:                                                                     objectIdentifier
1311:                                                                             .getCatalogName(),
1312:                                                                     catalog),
1313:                                                             objectIdentifier,
1314:                                                             resolvedTable,
1315:                                                             ignoreIfNotExists,
1316:                                                             false)));
1317:                         }
1318:                     },
1319:                     objectIdentifier,
1320:                     ignoreIfNotExists,
1321:                     "DropTable");
1322:         } else if (!ignoreIfNotExists) {
1323:             String tableOrView = isDropTable ? "Table" : "View";
1324:             throw new ValidationException(
1325:                     String.format(
1326:                             "%s with identifier '%s' does not exist.",
1327:                             tableOrView, objectIdentifier.asSummaryString()));
1328:         }
1329:     }
