1331:     /**
1332:      * A command that modifies given {@link Catalog} in an {@link ObjectPath}. This unifies error
1333:      * handling across different commands.
1334:      */
1335:     private interface ModifyCatalog {
1336: 
1337:         void execute(Catalog catalog, ObjectPath path) throws Exception;
1338:     }
1339: 
1340:     private void execute(
1341:             ModifyCatalog command,
1342:             ObjectIdentifier objectIdentifier,
1343:             boolean ignoreNoCatalog,
1344:             String commandName) {
1345:         Optional<Catalog> catalog = getCatalog(objectIdentifier.getCatalogName());
1346:         if (catalog.isPresent()) {
1347:             try {
1348:                 command.execute(catalog.get(), objectIdentifier.toObjectPath());
1349:             } catch (TableAlreadyExistException
1350:                     | TableNotExistException
1351:                     | DatabaseNotExistException e) {
1352:                 throw new ValidationException(getErrorMessage(objectIdentifier, commandName), e);
1353:             } catch (Exception e) {
1354:                 throw new TableException(getErrorMessage(objectIdentifier, commandName), e);
1355:             }
1356:         } else if (!ignoreNoCatalog) {
1357:             throw new ValidationException(
1358:                     String.format("Catalog %s does not exist.", objectIdentifier.getCatalogName()));
1359:         }
1360:     }
1361: 
1362:     private String getErrorMessage(ObjectIdentifier objectIdentifier, String commandName) {
1363:         return String.format("Could not execute %s in path %s", commandName, objectIdentifier);
1364:     }
