1366:     /** Resolves a {@link CatalogBaseTable} to a validated {@link ResolvedCatalogBaseTable}. */
1367:     public ResolvedCatalogBaseTable<?> resolveCatalogBaseTable(CatalogBaseTable baseTable) {
1368:         Preconditions.checkNotNull(schemaResolver, "Schema resolver is not initialized.");
1369:         if (baseTable instanceof CatalogTable) {
1370:             return resolveCatalogTable((CatalogTable) baseTable);
1371:         } else if (baseTable instanceof CatalogMaterializedTable) {
1372:             return resolveCatalogMaterializedTable((CatalogMaterializedTable) baseTable);
1373:         } else if (baseTable instanceof CatalogView) {
1374:             return resolveCatalogView((CatalogView) baseTable);
1375:         }
1376:         throw new IllegalArgumentException(
1377:                 "Unknown kind of catalog base table: " + baseTable.getClass());
1378:     }
