1408:                                                             bucketKey, physicalColumns));
1409:                                         }
1410:                                     });
1411: 
1412:                     distribution
1413:                             .getBucketCount()
1414:                             .ifPresent(
1415:                                     c -> {
1416:                                         if (c <= 0) {
1417:                                             throw new ValidationException(
1418:                                                     String.format(
1419:                                                             "Invalid bucket count '%s'. The number of "
1420:                                                                     + "buckets for a distributed table must be at least 1.",
1421:                                                             c));
1422:                                         }
1423:                                     });
