1428:         table.getPartitionKeys()
1429:                 .forEach(
1430:                         partitionKey -> {
1431:                             if (!physicalColumns.contains(partitionKey)) {
1432:                                 throw new ValidationException(
1433:                                         String.format(
1434:                                                 "Invalid partition key '%s'. A partition key must "
1435:                                                         + "reference a physical column in the schema. "
1436:                                                         + "Available columns are: %s",
1437:                                                 partitionKey, physicalColumns));
1438:                             }
1439:                         });
