414:      *     the {@link CatalogStore}, or if the remove operation failed.
415:      */
416:     public void unregisterCatalog(String catalogName, boolean ignoreIfNotExists) {
417:         checkArgument(
418:                 !StringUtils.isNullOrWhitespaceOnly(catalogName),
419:                 "Catalog name cannot be null or empty.");
420: 
421:         if (catalogs.containsKey(catalogName)
422:                 || catalogStoreHolder.catalogStore().contains(catalogName)) {
423:             if (catalogName.equals(currentCatalogName)) {
424:                 throw new CatalogException("Cannot drop a catalog which is currently in use.");
425:             }
426:             if (catalogs.containsKey(catalogName)) {
427:                 Catalog catalog = catalogs.remove(catalogName);
428:                 catalog.close();
429:             }
430:             if (catalogStoreHolder.catalogStore().contains(catalogName)) {
431:                 catalogStoreHolder.catalogStore().removeCatalog(catalogName, ignoreIfNotExists);
432:             }
433:         } else if (!ignoreIfNotExists) {
434:             throw new CatalogException(format("Catalog %s does not exist.", catalogName));
435:         }
436:     }
