998:     public void createTable(
999:             CatalogBaseTable table, ObjectIdentifier objectIdentifier, boolean ignoreIfExists) {
1000:         execute(
1001:                 (catalog, path) -> {
1002:                     ResolvedCatalogBaseTable<?> resolvedTable = resolveCatalogBaseTable(table);
1003:                     ResolvedCatalogBaseTable<?> resolvedListenedTable =
1004:                             managedTableListener.notifyTableCreation(
1005:                                     catalog,
1006:                                     objectIdentifier,
1007:                                     resolvedTable,
1008:                                     false,
1009:                                     ignoreIfExists);
1010: 
1011:                     catalog.createTable(path, resolvedListenedTable, ignoreIfExists);
1012:                     if (resolvedListenedTable instanceof CatalogTable
1013:                             || resolvedListenedTable instanceof CatalogMaterializedTable) {
1014:                         catalogModificationListeners.forEach(
1015:                                 listener ->
1016:                                         listener.onEvent(
1017:                                                 CreateTableEvent.createEvent(
1018:                                                         CatalogContext.createContext(
1019:                                                                 objectIdentifier.getCatalogName(),
1020:                                                                 catalog),
1021:                                                         objectIdentifier,
1022:                                                         resolvedListenedTable,
1023:                                                         ignoreIfExists,
1024:                                                         false)));
1025:                     }
1026:                 },
1027:                 objectIdentifier,
1028:                 false,
1029:                 "CreateTable");
