95:     @Test
96:     void testCreateMaterializedTableInContinuousMode() throws Exception {
97:         String materializedTableDDL =
98:                 "CREATE MATERIALIZED TABLE users_shops"
99:                         + " PARTITIONED BY (ds)\n"
100:                         + " WITH(\n"
101:                         + "   'format' = 'debezium-json'\n"
102:                         + " )\n"
103:                         + " FRESHNESS = INTERVAL '30' SECOND\n"
104:                         + " AS SELECT \n"
105:                         + "  user_id,\n"
106:                         + "  shop_id,\n"
107:                         + "  ds,\n"
108:                         + "  SUM (payment_amount_cents) AS payed_buy_fee_sum,\n"
109:                         + "  SUM (1) AS pv\n"
110:                         + " FROM (\n"
111:                         + "    SELECT user_id, shop_id, DATE_FORMAT(order_created_at, 'yyyy-MM-dd') AS ds, payment_amount_cents FROM datagenSource"
112:                         + " ) AS tmp\n"
113:                         + " GROUP BY (user_id, shop_id, ds)";
114:         OperationHandle materializedTableHandle =
115:                 service.executeStatement(
116:                         sessionHandle, materializedTableDDL, -1, new Configuration());
117:         awaitOperationTermination(service, sessionHandle, materializedTableHandle);
118: 
119:         // validate materialized table: schema, refresh mode, refresh status, refresh handler,
120:         // doesn't check the data because it generates randomly.
121:         ResolvedCatalogMaterializedTable actualMaterializedTable =
122:                 (ResolvedCatalogMaterializedTable)
123:                         service.getTable(
124:                                 sessionHandle,
125:                                 ObjectIdentifier.of(
126:                                         fileSystemCatalogName,
127:                                         TEST_DEFAULT_DATABASE,
128:                                         "users_shops"));
129: 
130:         // Expected schema
131:         ResolvedSchema expectedSchema =
132:                 ResolvedSchema.of(
133:                         Arrays.asList(
134:                                 Column.physical("user_id", DataTypes.BIGINT()),
135:                                 Column.physical("shop_id", DataTypes.BIGINT()),
136:                                 Column.physical("ds", DataTypes.STRING()),
137:                                 Column.physical("payed_buy_fee_sum", DataTypes.BIGINT()),
138:                                 Column.physical("pv", DataTypes.INT().notNull())));
139: 
140:         assertThat(actualMaterializedTable.getResolvedSchema()).isEqualTo(expectedSchema);
141:         assertThat(actualMaterializedTable.getFreshness()).isEqualTo(Duration.ofSeconds(30));
142:         assertThat(actualMaterializedTable.getLogicalRefreshMode())
143:                 .isEqualTo(CatalogMaterializedTable.LogicalRefreshMode.AUTOMATIC);
144:         assertThat(actualMaterializedTable.getRefreshMode())
145:                 .isEqualTo(CatalogMaterializedTable.RefreshMode.CONTINUOUS);
146:         assertThat(actualMaterializedTable.getRefreshStatus())
147:                 .isEqualTo(CatalogMaterializedTable.RefreshStatus.ACTIVATED);
148:         assertThat(actualMaterializedTable.getRefreshHandlerDescription()).isNotEmpty();
149:         assertThat(actualMaterializedTable.getSerializedRefreshHandler()).isNotEmpty();
150: 
151:         ContinuousRefreshHandler activeRefreshHandler =
152:                 ContinuousRefreshHandlerSerializer.INSTANCE.deserialize(
153:                         actualMaterializedTable.getSerializedRefreshHandler(),
154:                         getClass().getClassLoader());
155: 
156:         waitUntilAllTasksAreRunning(
157:                 restClusterClient, JobID.fromHexString(activeRefreshHandler.getJobId()));
158: 
159:         // verify the background job is running
160:         String describeJobDDL = String.format("DESCRIBE JOB '%s'", activeRefreshHandler.getJobId());
161:         OperationHandle describeJobHandle =
162:                 service.executeStatement(sessionHandle, describeJobDDL, -1, new Configuration());
163:         awaitOperationTermination(service, sessionHandle, describeJobHandle);
164:         List<RowData> jobResults = fetchAllResults(service, sessionHandle, describeJobHandle);
165:         assertThat(jobResults.get(0).getString(2).toString()).isEqualTo("RUNNING");
166: 
167:         // get checkpoint interval
168:         long checkpointInterval =
169:                 getCheckpointIntervalConfig(restClusterClient, activeRefreshHandler.getJobId());
170:         assertThat(checkpointInterval).isEqualTo(30 * 1000);
171:     }
