329:     /**
330:      * Create a {@link ArchivedExecutionGraph} from the given {@link ExecutionGraph}.
331:      *
332:      * @param executionGraph to create the ArchivedExecutionGraph from
333:      * @param statusOverride optionally overrides the JobStatus of the ExecutionGraph with a
334:      *     non-globally-terminal state and clears timestamps of globally-terminal states
335:      * @return ArchivedExecutionGraph created from the given ExecutionGraph
336:      */
337:     public static ArchivedExecutionGraph createFrom(
338:             ExecutionGraph executionGraph, @Nullable JobStatus statusOverride) {
339:         Preconditions.checkArgument(
340:                 statusOverride == null || !statusOverride.isGloballyTerminalState(),
341:                 "Status override is only allowed for non-globally-terminal states.");
342: 
343:         Map<JobVertexID, ArchivedExecutionJobVertex> archivedTasks = new HashMap<>();
344:         List<ArchivedExecutionJobVertex> archivedVerticesInCreationOrder = new ArrayList<>();
345: 
346:         for (ExecutionJobVertex task : executionGraph.getVerticesTopologically()) {
347:             ArchivedExecutionJobVertex archivedTask = task.archive();
348:             archivedVerticesInCreationOrder.add(archivedTask);
349:             archivedTasks.put(task.getJobVertexId(), archivedTask);
350:         }
351: 
352:         final Map<String, SerializedValue<OptionalFailure<Object>>> serializedUserAccumulators =
353:                 executionGraph.getAccumulatorsSerialized();
354: 
355:         final long[] timestamps = new long[JobStatus.values().length];
356: 
357:         // if the state is overridden with a non-globally-terminal state then we need to erase
358:         // traces of globally-terminal states for consistency
359:         final boolean clearGloballyTerminalStateTimestamps = statusOverride != null;
360: 
361:         for (JobStatus jobStatus : JobStatus.values()) {
362:             final int ordinal = jobStatus.ordinal();
363:             if (!(clearGloballyTerminalStateTimestamps && jobStatus.isGloballyTerminalState())) {
364:                 timestamps[ordinal] = executionGraph.getStatusTimestamp(jobStatus);
365:             }
366:         }
367: 
368:         return new ArchivedExecutionGraph(
369:                 executionGraph.getJobID(),
370:                 executionGraph.getJobName(),
371:                 archivedTasks,
372:                 archivedVerticesInCreationOrder,
373:                 timestamps,
374:                 statusOverride == null ? executionGraph.getState() : statusOverride,
375:                 executionGraph.getJobType(),
376:                 executionGraph.getFailureInfo(),
377:                 executionGraph.getPlan(),
378:                 executionGraph.getAccumulatorResultsStringified(),
379:                 serializedUserAccumulators,
380:                 executionGraph.getArchivedExecutionConfig(),
381:                 executionGraph.isStoppable(),
382:                 executionGraph.getCheckpointCoordinatorConfiguration(),
383:                 executionGraph.getCheckpointStatsSnapshot(),
384:                 executionGraph.getStateBackendName().orElse(null),
385:                 executionGraph.getCheckpointStorageName().orElse(null),
386:                 executionGraph.isChangelogStateBackendEnabled(),
387:                 executionGraph.getChangelogStorageName().orElse(null),
388:                 executionGraph.getStreamGraphJson(),
389:                 executionGraph.getPendingOperatorCount());
390:     }
