77: /**
78:  * This rule checks if a {@link UnresolvedCallExpression} can work with the given arguments and
79:  * infers the output data type. All function calls are resolved {@link CallExpression} after
80:  * applying this rule.
81:  *
82:  * <p>This rule also resolves {@code flatten()} calls on composite types.
83:  *
84:  * <p>If the call expects different types of arguments, but the given arguments have types that can
85:  * be cast, a {@link BuiltInFunctionDefinitions#CAST} expression is inserted.
86:  *
87:  * <p>It validates and prepares inline, unregistered {@link UserDefinedFunction}s.
88:  */
89: @Internal
90: final class ResolveCallByArgumentsRule implements ResolverRule {
91: 
92:     @Override
93:     public List<Expression> apply(List<Expression> expression, ResolutionContext context) {
94:         // only the top-level expressions may access the output data type
95:         final SurroundingInfo surroundingInfo =
96:                 context.getOutputDataType().map(SurroundingInfo::of).orElse(null);
97:         return expression.stream()
98:                 .flatMap(e -> e.accept(new ResolvingCallVisitor(context, surroundingInfo)).stream())
99:                 .collect(Collectors.toList());
100:     }
101: 
102:     // --------------------------------------------------------------------------------------------
103: 
104:     private static class ResolvingCallVisitor
105:             extends RuleExpressionVisitor<List<ResolvedExpression>> {
106: 
107:         private final @Nullable SurroundingInfo surroundingInfo;
108: 
109:         ResolvingCallVisitor(ResolutionContext context, @Nullable SurroundingInfo surroundingInfo) {
110:             super(context);
111:             this.surroundingInfo = surroundingInfo;
112:         }
113: 
114:         @Override
115:         public List<ResolvedExpression> visit(UnresolvedCallExpression unresolvedCall) {
116:             final FunctionDefinition definition;
117:             // clean functions that were not registered in a catalog
118:             if (unresolvedCall.getFunctionIdentifier().isEmpty()) {
119:                 definition =
120:                         prepareInlineUserDefinedFunction(unresolvedCall.getFunctionDefinition());
121:             } else {
122:                 definition = unresolvedCall.getFunctionDefinition();
123:             }
124: 
125:             final String functionName =
126:                     unresolvedCall
127:                             .getFunctionIdentifier()
128:                             .map(FunctionIdentifier::toString)
129:                             .orElseGet(definition::toString);
130: 
131:             final TypeInference typeInference = getTypeInferenceOrNull(definition);
132: 
133:             // Reorder named arguments and add replacements for optional ones
134:             final UnresolvedCallExpression adaptedCall =
135:                     executeAssignment(functionName, definition, typeInference, unresolvedCall);
136: 
137:             // resolve the children with information from the current call
138:             final List<ResolvedExpression> resolvedArgs = new ArrayList<>();
139:             final int argCount = adaptedCall.getChildren().size();
140: 
141:             for (int i = 0; i < argCount; i++) {
142:                 final SurroundingInfo surroundingInfo;
143:                 if (typeInference == null) {
144:                     surroundingInfo = null;
145:                 } else {
146:                     surroundingInfo =
147:                             SurroundingInfo.of(
148:                                     functionName,
149:                                     definition,
150:                                     typeInference,
151:                                     argCount,
152:                                     i,
153:                                     resolutionContext.isGroupedAggregation());
154:                 }
155:                 final ResolvingCallVisitor childResolver =
156:                         new ResolvingCallVisitor(resolutionContext, surroundingInfo);
157:                 resolvedArgs.addAll(adaptedCall.getChildren().get(i).accept(childResolver));
158:             }
159: 
160:             if (definition == BuiltInFunctionDefinitions.FLATTEN) {
161:                 return executeFlatten(resolvedArgs);
162:             }
163: 
164:             return Collections.singletonList(
165:                     runTypeInference(
166:                             functionName,
167:                             adaptedCall,
168:                             typeInference,
169:                             resolvedArgs,
170:                             surroundingInfo));
171:         }
172: 
173:         @Override
174:         protected List<ResolvedExpression> defaultMethod(Expression expression) {
175:             if (expression instanceof ResolvedExpression) {
176:                 return Collections.singletonList((ResolvedExpression) expression);
177:             }
178:             throw new TableException("Unexpected unresolved expression: " + expression);
179:         }
180: 
181:         private List<ResolvedExpression> executeFlatten(List<ResolvedExpression> args) {
182:             if (args.size() != 1) {
183:                 throw new ValidationException("Invalid number of arguments for flattening.");
184:             }
185:             final ResolvedExpression composite = args.get(0);
186:             final LogicalType compositeType = composite.getOutputDataType().getLogicalType();
187:             if (hasLegacyTypes(compositeType)) {
188:                 return flattenLegacyCompositeType(composite);
189:             }
190:             return flattenCompositeType(composite);
191:         }
192: 
193:         private List<ResolvedExpression> flattenCompositeType(ResolvedExpression composite) {
194:             final DataType dataType = composite.getOutputDataType();
195:             final LogicalType type = dataType.getLogicalType();
196:             if (!isCompositeType(type)) {
197:                 return singletonList(composite);
198:             }
199:             final List<DataType> fieldDataTypes = DataTypeUtils.flattenToDataTypes(dataType);
200:             final List<String> fieldNames = DataTypeUtils.flattenToNames(dataType);
201:             return IntStream.range(0, fieldDataTypes.size())
202:                     .mapToObj(
203:                             idx -> {
204:                                 final DataType fieldDataType = fieldDataTypes.get(idx);
205:                                 final DataType nullableFieldDataType;
206:                                 if (type.isNullable()) {
207:                                     nullableFieldDataType = fieldDataType.nullable();
208:                                 } else {
209:                                     nullableFieldDataType = fieldDataType;
210:                                 }
211:                                 return resolutionContext
212:                                         .postResolutionFactory()
213:                                         .get(
214:                                                 composite,
215:                                                 valueLiteral(fieldNames.get(idx)),
216:                                                 nullableFieldDataType);
217:                             })
218:                     .collect(Collectors.toList());
219:         }
220: 
221:         private List<ResolvedExpression> flattenLegacyCompositeType(ResolvedExpression composite) {
222:             final TypeInformation<?> resultType =
223:                     fromDataTypeToLegacyInfo(composite.getOutputDataType());
224:             if (!(resultType instanceof CompositeType)) {
225:                 return singletonList(composite);
226:             }
227:             final CompositeType<?> compositeType = (CompositeType<?>) resultType;
228:             return IntStream.range(0, resultType.getArity())
229:                     .mapToObj(
230:                             idx ->
231:                                     resolutionContext
232:                                             .postResolutionFactory()
233:                                             .get(
234:                                                     composite,
235:                                                     valueLiteral(
236:                                                             compositeType.getFieldNames()[idx]),
237:                                                     fromLegacyInfoToDataType(
238:                                                             compositeType.getTypeAt(idx))))
239:                     .collect(Collectors.toList());
240:         }
241: 
242:         /** Temporary method until all calls define a type inference. */
243:         private @Nullable TypeInference getTypeInferenceOrNull(FunctionDefinition definition) {
244:             final TypeInference inference =
245:                     definition.getTypeInference(resolutionContext.typeFactory());
246:             if (inference.getOutputTypeStrategy() != TypeStrategies.MISSING) {
247:                 return inference;
248:             } else {
249:                 return null;
250:             }
251:         }
252: 
253:         private UnresolvedCallExpression executeAssignment(
254:                 String functionName,
255:                 FunctionDefinition definition,
256:                 @Nullable TypeInference inference,
257:                 UnresolvedCallExpression unresolvedCall) {
258:             // Assignment cannot be a top-level expression,
259:             // it must be located within a function call
260:             if (definition == BuiltInFunctionDefinitions.ASSIGNMENT) {
261:                 throw new ValidationException(
262:                         "Named arguments via asArgument() can only be used within function calls.");
263:             }
264:             // Skip assignment for special calls
265:             if (inference == null) {
266:                 return unresolvedCall;
267:             }
268: 
269:             final List<Expression> actualArgs = unresolvedCall.getChildren();
270:             final Map<String, Expression> namedArgs = new HashMap<>();
271:             actualArgs.stream()
272:                     .map(this::extractAssignment)
273:                     .filter(Objects::nonNull)
274:                     .forEach(
275:                             assignment -> {
276:                                 if (namedArgs.containsKey(assignment.getKey())) {
277:                                     throw new ValidationException(
278:                                             String.format(
279:                                                     "Invalid call to function '%s'. "
280:                                                             + "Duplicate named argument found: %s",
281:                                                     functionName, assignment.getKey()));
282:                                 }
283:                                 namedArgs.put(assignment.getKey(), assignment.getValue());
284:                             });
285:             if (namedArgs.isEmpty()) {
286:                 // Use position-based call
287:                 return unresolvedCall;
288:             }
289: 
290:             final List<StaticArgument> declaredArgs = inference.getStaticArguments().orElse(null);
291:             if (declaredArgs == null) {
292:                 throw new ValidationException(
293:                         String.format(
294:                                 "Invalid call to function '%s'. "
295:                                         + "The function does not support named arguments. "
296:                                         + "Please pass the arguments based on positions (i.e. without asArgument()).",
297:                                 functionName));
298:             }
299: 
300:             // Fill optional arguments
301:             declaredArgs.forEach(
302:                     declaredArg -> {
303:                         if (declaredArg.isOptional()) {
304:                             // All optional arguments have a type.
305:                             // This is checked in StaticArgument.
306:                             final DataType dataType =
307:                                     declaredArg
308:                                             .getDataType()
309:                                             .orElseThrow(IllegalStateException::new);
310:                             namedArgs.putIfAbsent(
311:                                     declaredArg.getName(),
312:                                     CallExpression.permanent(
313:                                             BuiltInFunctionDefinitions.DEFAULT,
314:                                             List.of(),
315:                                             dataType));
316:                         }
317:                     });
318: 
319:             if (declaredArgs.size() != namedArgs.size()) {
320:                 final Set<String> providedArgs = namedArgs.keySet();
321:                 final Set<String> knownArgs =
322:                         declaredArgs.stream()
323:                                 .map(StaticArgument::getName)
324:                                 .collect(Collectors.toSet());
325:                 final Set<String> unknownArgs =
326:                         providedArgs.stream()
327:                                 .filter(arg -> !knownArgs.contains(arg))
328:                                 .collect(Collectors.toSet());
329:                 final String cause;
330:                 if (!unknownArgs.isEmpty()) {
331:                     cause = "Unknown argument names: " + unknownArgs;
332:                 } else {
333:                     final List<StaticArgument> missingArgs =
334:                             declaredArgs.stream()
335:                                     .filter(arg -> !providedArgs.contains(arg.getName()))
336:                                     .collect(Collectors.toList());
337:                     cause = "Missing required arguments: " + missingArgs;
338:                 }
339:                 throw new ValidationException(
340:                         String.format(
341:                                 "Invalid call to function '%s'. If the call uses named arguments, "
342:                                         + "a valid name has to be provided for all passed arguments. %s",
343:                                 functionName, cause));
344:             }
345: 
346:             final List<Expression> reorderedArgs =
347:                     declaredArgs.stream()
348:                             .map(arg -> namedArgs.get(arg.getName()))
349:                             .collect(Collectors.toList());
350:             return unresolvedCall.replaceArgs(reorderedArgs);
351:         }
352: 
353:         private Map.Entry<String, Expression> extractAssignment(Expression e) {
354:             final List<Expression> children = e.getChildren();
355:             if (!isFunction(e, BuiltInFunctionDefinitions.ASSIGNMENT) || children.size() != 2) {
356:                 return null;
357:             }
358:             final String name = ExpressionUtils.stringValue(children.get(0));
359:             if (name == null) {
360:                 return null;
361:             }
362:             return Map.entry(name, children.get(1));
363:         }
364: 
365:         private ResolvedExpression runTypeInference(
366:                 String functionName,
367:                 UnresolvedCallExpression unresolvedCall,
368:                 TypeInference inference,
369:                 List<ResolvedExpression> resolvedArgs,
370:                 @Nullable SurroundingInfo surroundingInfo) {
371:             if (inference == null) {
372:                 throw new TableException(
373:                         "Could not get a type inference for function: " + functionName);
374:             }
375: 
376:             final Result inferenceResult =
377:                     TypeInferenceUtil.runTypeInference(
378:                             inference,
379:                             new TableApiCallContext(
380:                                     resolutionContext.typeFactory(),
381:                                     functionName,
382:                                     unresolvedCall.getFunctionDefinition(),
383:                                     resolvedArgs,
384:                                     resolutionContext.isGroupedAggregation()),
385:                             surroundingInfo);
386: 
387:             final List<ResolvedExpression> adaptedArguments =
388:                     castArguments(inferenceResult, resolvedArgs);
389: 
390:             return unresolvedCall.resolve(adaptedArguments, inferenceResult.getOutputDataType());
391:         }
392: 
393:         /** Casts the arguments according to the properties of the {@link Result}. */
394:         private List<ResolvedExpression> castArguments(
395:                 Result inferenceResult, List<ResolvedExpression> resolvedArgs) {
396: 
397:             return IntStream.range(0, resolvedArgs.size())
398:                     .mapToObj(
399:                             pos -> {
400:                                 final ResolvedExpression argument = resolvedArgs.get(pos);
401:                                 final DataType argumentType = argument.getOutputDataType();
402:                                 final DataType expectedType =
403:                                         inferenceResult.getExpectedArgumentTypes().get(pos);
404: 
405:                                 if (!supportsAvoidingCast(
406:                                         argumentType.getLogicalType(),
407:                                         expectedType.getLogicalType())) {
408:                                     return resolutionContext
409:                                             .postResolutionFactory()
410:                                             .cast(argument, expectedType);
411:                                 }
412:                                 return argument;
413:                             })
414:                     .collect(Collectors.toList());
415:         }
