68: import static org.apache.flink.table.expressions.ApiExpressionUtils.isFunction;
69: import static org.apache.flink.table.expressions.ApiExpressionUtils.unresolvedCall;
70: import static org.apache.flink.table.expressions.ApiExpressionUtils.valueLiteral;
71: import static org.apache.flink.table.types.logical.utils.LogicalTypeCasts.supportsAvoidingCast;
72: import static org.apache.flink.table.types.logical.utils.LogicalTypeChecks.hasLegacyTypes;
73: import static org.apache.flink.table.types.logical.utils.LogicalTypeChecks.isCompositeType;
