1648:                 runIfSupported(CheckpointStatsListener::onFailedCheckpoint, "onFailedCheckpoint");
1649:             }
1650: 
1651:             @Override
1652:             public void onCompletedCheckpoint() {
1653:                 runIfSupported(
1654:                         CheckpointStatsListener::onCompletedCheckpoint, "onCompletedCheckpoint");
1655:             }
1656: 
1657:             private void runIfSupported(
1658:                     ThrowingConsumer<CheckpointStatsListener, RuntimeException> callback,
1659:                     String callbackLabel) {
1660:                 AdaptiveScheduler.this
1661:                         .getMainThreadExecutor()
1662:                         .execute(
1663:                                 () ->
1664:                                         state.tryRun(
1665:                                                 CheckpointStatsListener.class,
1666:                                                 callback,
1667:                                                 logger ->
1668:                                                         logger.debug(
1669:                                                                 "{} is not supported by {}.",
1670:                                                                 callbackLabel,
1671:                                                                 state.getClass().getName())));
1672:             }
1673:         };
1674:     }
