511:     /**
512:      * A stub which helps to:
513:      *
514:      * <p>1. Get source tasks' information. (Such as {@link ResultPartitionID}).
515:      *
516:      * <p>2. Manually control the execution of source task. Helps to block and unblock execution of
517:      * source task.
518:      *
519:      * <p>This operator should be chained with source operator.
520:      */
521:     private static class SourceTail extends AbstractStreamOperator<Long>
522:             implements OneInputStreamOperator<Long, Long> {
523: 
524:         public static Map<Integer, Boolean> subtaskBlocked = new ConcurrentHashMap<>();
525:         public static Map<Integer, ResultPartitionID> resultPartitions = new ConcurrentHashMap<>();
526:         public static Map<Integer, Integer> attemptIds = new ConcurrentHashMap<>();
527: 
528:         public SourceTail() {
529:             super();
530:         }
531: 
532:         @Override
533:         protected void setup(
534:                 StreamTask<?, ?> containingTask,
535:                 StreamConfig config,
536:                 Output<StreamRecord<Long>> output) {
537:             super.setup(containingTask, config, output);
538: 
539:             int subIdx = getRuntimeContext().getTaskInfo().getIndexOfThisSubtask();
540: 
541:             // attempt id ++
542:             attemptIds.compute(
543:                     subIdx,
544:                     (ignored, value) -> {
545:                         if (value == null) {
546:                             value = 0;
547:                         } else {
548:                             value += 1;
549:                         }
550:                         return value;
551:                     });
552: 
553:             // record result partition id.
554:             Environment environment = getContainingTask().getEnvironment();
555:             checkState(environment.getAllWriters().length == 1);
556:             resultPartitions.put(subIdx, environment.getAllWriters()[0].getPartitionId());
557: 
558:             // wait until unblocked.
559:             if (subtaskBlocked.containsKey(subIdx) && subtaskBlocked.get(subIdx)) {
560:                 tryWaitUntilCondition(() -> !subtaskBlocked.get(subIdx));
561:             }
562:         }
563: 
564:         @Override
565:         public void processElement(StreamRecord<Long> streamRecord) throws Exception {
566:             output.collect(streamRecord);
567:         }
568: 
569:         public static void clear() {
570:             subtaskBlocked.clear();
571:             attemptIds.clear();
572:             resultPartitions.clear();
573:         }
574: 
575:         public static void blockSubTasks(Integer... subIndices) {
576:             setSubtaskBlocked(Arrays.asList(subIndices), true, subtaskBlocked);
577:         }
578: 
579:         public static void unblockSubTasks(Integer... subIndices) {
580:             setSubtaskBlocked(Arrays.asList(subIndices), false, subtaskBlocked);
581:         }
582:     }
