719:                             value += 1;
720:                         }
721:                         return value;
722:                     });
723: 
724:             // wait until unblocked.
725:             if (subtaskBlocked.containsKey(subIdx) && subtaskBlocked.get(subIdx)) {
726:                 tryWaitUntilCondition(() -> !subtaskBlocked.get(subIdx));
727:             }
