768:     private void deleteOldestFileInShuffleNettyDirectory(File directory) {
769:         if (directory == null || !directory.exists() || !directory.isDirectory()) {
770:             return;
771:         }
772: 
773:         File[] matchingDirectories =
774:                 directory.listFiles(
775:                         file ->
776:                                 file.isDirectory()
777:                                         && file.getName().startsWith("flink-netty-shuffle"));
778: 
779:         if (matchingDirectories == null) {
780:             return;
781:         }
782: 
783:         List<File> files = new ArrayList<>();
784:         for (File subdirectory : matchingDirectories) {
785:             Arrays.stream(subdirectory.listFiles())
786:                     .filter(file -> file.getName().endsWith(PartitionedFile.DATA_FILE_SUFFIX))
787:                     .forEach(files::add);
788:         }
789: 
790:         if (!files.isEmpty()) {
791:             files.sort(Comparator.comparing(this::getFileCreationTime));
792:             files.get(0).delete();
793:         }
794:     }
795: 
796:     private long getFileCreationTime(File file) {
797:         try {
798:             BasicFileAttributes attrs =
799:                     Files.readAttributes(file.toPath(), BasicFileAttributes.class);
800:             return attrs.creationTime().toMillis();
801:         } catch (NoSuchFileException e) {
802:             // TaskExecutor will delete unfinished partition file asynchronously when jom failover.
803:             return Long.MAX_VALUE;
804:         } catch (IOException e) {
805:             throw new RuntimeException(e);
806:         }
807:     }
808: }
