48: import java.util.List;
49: import java.util.Optional;
50: import java.util.concurrent.CompletableFuture;
51: import java.util.concurrent.CompletionException;
52: import java.util.concurrent.ExecutorService;
53: import java.util.concurrent.Executors;
54: 
55: import static org.apache.flink.util.Preconditions.checkNotNull;
56: 
57: /**
58:  * A base class for {@link PipelineExecutor executors} that invoke directly methods of the {@link
59:  * org.apache.flink.runtime.dispatcher.DispatcherGateway Dispatcher} and do not go through the REST
60:  * API.
61:  */
62: @Internal
63: public class EmbeddedExecutor implements PipelineExecutor {
64: 
65:     private static final Logger LOG = LoggerFactory.getLogger(EmbeddedExecutor.class);
66: 
67:     private final ExecutorService executorService =
68:             Executors.newFixedThreadPool(
69:                     1, new ExecutorThreadFactory("Flink-EmbeddedClusterExecutor-IO"));
70: 
71:     public static final String NAME = "embedded";
72: 
73:     private final Collection<JobID> submittedJobIds;
74: 
75:     private final DispatcherGateway dispatcherGateway;
76: 
77:     private final EmbeddedJobClientCreator jobClientCreator;
78: 
79:     private final List<JobStatusChangedListener> jobStatusChangedListeners;
80: 
81:     /**
82:      * Creates a {@link EmbeddedExecutor}.
83:      *
84:      * @param submittedJobIds a list that is going to be filled with the job ids of the new jobs
85:      *     that will be submitted. This is essentially used to return the submitted job ids to the
86:      *     caller.
87:      * @param dispatcherGateway the dispatcher of the cluster which is going to be used to submit
88:      *     jobs.
89:      * @param configuration the flink application configuration
90:      * @param jobClientCreator the job client creator
91:      */
92:     public EmbeddedExecutor(
93:             final Collection<JobID> submittedJobIds,
94:             final DispatcherGateway dispatcherGateway,
95:             final Configuration configuration,
96:             final EmbeddedJobClientCreator jobClientCreator) {
97:         this.submittedJobIds = checkNotNull(submittedJobIds);
98:         this.dispatcherGateway = checkNotNull(dispatcherGateway);
99:         this.jobClientCreator = checkNotNull(jobClientCreator);
100:         this.jobStatusChangedListeners =
101:                 JobStatusChangedListenerUtils.createJobStatusChangedListeners(
102:                         Thread.currentThread().getContextClassLoader(),
103:                         configuration,
104:                         executorService);
105:     }
106: 
107:     @Override
108:     public CompletableFuture<JobClient> execute(
109:             final Pipeline pipeline,
110:             final Configuration configuration,
111:             ClassLoader userCodeClassloader)
112:             throws MalformedURLException {
113:         checkNotNull(pipeline);
114:         checkNotNull(configuration);
115: 
116:         final Optional<JobID> optJobId =
117:                 configuration
118:                         .getOptional(PipelineOptionsInternal.PIPELINE_FIXED_JOB_ID)
119:                         .map(JobID::fromHexString);
120: 
121:         if (optJobId.isPresent() && submittedJobIds.contains(optJobId.get())) {
122:             return getJobClientFuture(optJobId.get(), userCodeClassloader);
123:         }
124: 
125:         return submitAndGetJobClientFuture(pipeline, configuration, userCodeClassloader);
126:     }
127: 
128:     private CompletableFuture<JobClient> getJobClientFuture(
129:             final JobID jobId, final ClassLoader userCodeClassloader) {
130:         LOG.info("Job {} was recovered successfully.", jobId);
131:         return CompletableFuture.completedFuture(
132:                 jobClientCreator.getJobClient(jobId, userCodeClassloader));
133:     }
134: 
135:     private CompletableFuture<JobClient> submitAndGetJobClientFuture(
136:             final Pipeline pipeline,
137:             final Configuration configuration,
138:             final ClassLoader userCodeClassloader)
139:             throws MalformedURLException {
140:         final Duration timeout = configuration.get(ClientOptions.CLIENT_TIMEOUT);
141: 
142:         final StreamGraph streamGraph =
143:                 PipelineExecutorUtils.getStreamGraph(pipeline, configuration, userCodeClassloader);
144:         final JobID actualJobId = streamGraph.getJobID();
145: 
146:         this.submittedJobIds.add(actualJobId);
147:         LOG.info("Job {} is submitted.", actualJobId);
148: 
149:         if (LOG.isDebugEnabled()) {
150:             LOG.debug("Effective Configuration: {}", configuration);
151:         }
152: 
153:         final CompletableFuture<JobID> jobSubmissionFuture =
154:                 submitJob(configuration, dispatcherGateway, streamGraph, timeout);
155: 
156:         return jobSubmissionFuture
157:                 .thenApplyAsync(
158:                         FunctionUtils.uncheckedFunction(
159:                                 jobId -> {
160:                                     org.apache.flink.client.ClientUtils
161:                                             .waitUntilJobInitializationFinished(
162:                                                     () ->
163:                                                             dispatcherGateway
164:                                                                     .requestJobStatus(
165:                                                                             jobId, timeout)
166:                                                                     .get(),
167:                                                     () ->
168:                                                             dispatcherGateway
169:                                                                     .requestJobResult(
170:                                                                             jobId, timeout)
171:                                                                     .get(),
172:                                                     userCodeClassloader);
173:                                     return jobId;
174:                                 }))
175:                 .thenApplyAsync(
176:                         jobID -> jobClientCreator.getJobClient(actualJobId, userCodeClassloader))
177:                 .whenCompleteAsync(
178:                         (jobClient, throwable) -> {
179:                             if (throwable == null) {
180:                                 PipelineExecutorUtils.notifyJobStatusListeners(
181:                                         pipeline, streamGraph, jobStatusChangedListeners);
182:                             } else {
183:                                 LOG.error(
184:                                         "Failed to submit job graph to application cluster",
185:                                         throwable);
186:                             }
187:                         });
188:     }
189: 
190:     private static CompletableFuture<JobID> submitJob(
191:             final Configuration configuration,
192:             final DispatcherGateway dispatcherGateway,
193:             final ExecutionPlan executionPlan,
194:             final Duration rpcTimeout) {
195:         checkNotNull(executionPlan);
196: 
197:         LOG.info("Submitting Job with JobId={}.", executionPlan.getJobID());
198: 
199:         return dispatcherGateway
200:                 .getBlobServerPort(rpcTimeout)
201:                 .thenApply(
202:                         blobServerPort ->
203:                                 new InetSocketAddress(
204:                                         dispatcherGateway.getHostname(), blobServerPort))
205:                 .thenCompose(
206:                         blobServerAddress -> {
207:                             try {
208:                                 ClientUtils.extractAndUploadExecutionPlanFiles(
209:                                         executionPlan,
210:                                         () -> new BlobClient(blobServerAddress, configuration));
211:                             } catch (FlinkException e) {
212:                                 throw new CompletionException(e);
213:                             }
214: 
215:                             return dispatcherGateway.submitJob(executionPlan, rpcTimeout);
216:                         })
217:                 .thenApply(ack -> executionPlan.getJobID());
218:     }
219: }
