425:             implements Comparator<Tuple2<T0, T1>> {
426:         @Override
427:         public int compare(Tuple2<T0, T1> o1, Tuple2<T0, T1> o2) {
428:             int cmp = o1.f0.compareTo(o2.f0);
429: 
430:             if (cmp != 0) {
431:                 return cmp;
432:             }
433: 
434:             return o1.f1.compareTo(o2.f1);
435:         }
436:     }
