1140:     /** Test source producing (key, 1) tuples with random key in key range (numKeys). */
1141:     private static class TestKeyRangeSource
1142:             extends RichParallelSourceFunction<Tuple2<Integer, Long>>
1143:             implements CheckpointListener {
1144: 
1145:         private static final long serialVersionUID = -5744725196953582710L;
1146: 
1147:         private static final AtomicLong LATEST_CHECKPOINT_ID = new AtomicLong();
1148:         private final int numKeys;
1149:         private final ThreadLocalRandom random = ThreadLocalRandom.current();
1150:         private volatile boolean isRunning = true;
1151:         private int counter = 0;
1152: 
1153:         TestKeyRangeSource(int numKeys) {
1154:             this.numKeys = numKeys;
1155:         }
1156: 
1157:         @Override
1158:         public void open(OpenContext openContext) throws Exception {
1159:             super.open(openContext);
1160:             if (getRuntimeContext().getTaskInfo().getIndexOfThisSubtask() == 0) {
1161:                 LATEST_CHECKPOINT_ID.set(0L);
1162:             }
1163:         }
1164: 
1165:         @Override
1166:         public void run(SourceContext<Tuple2<Integer, Long>> ctx) throws Exception {
1167:             // f0 => key
1168:             Tuple2<Integer, Long> record = new Tuple2<>(0, 1L);
1169: 
1170:             while (isRunning) {
1171:                 synchronized (ctx.getCheckpointLock()) {
1172:                     record.f0 = random.nextInt(numKeys);
1173:                     ctx.collect(record);
1174:                     counter++;
1175:                 }
1176: 
1177:                 if (counter % 50 == 0) {
1178:                     // mild slow down
