399:     private static String runJobAndGetExternalizedCheckpoint(
400:             StateBackend backend,
401:             @Nullable String externalCheckpoint,
402:             MiniClusterWithClientResource cluster,
403:             RecoveryClaimMode recoveryClaimMode)
404:             throws Exception {
405:         // complete at least two checkpoints so that the initial checkpoint can be subsumed
406:         return runJobAndGetExternalizedCheckpoint(
407:                 backend,
408:                 externalCheckpoint,
409:                 cluster,
410:                 recoveryClaimMode,
411:                 new Configuration(),
412:                 2,
413:                 true);
414:     }
415: 
416:     static String runJobAndGetExternalizedCheckpoint(
417:             StateBackend backend,
418:             @Nullable String externalCheckpoint,
419:             MiniClusterWithClientResource cluster,
420:             RecoveryClaimMode recoveryClaimMode,
421:             Configuration jobConfig,
422:             int consecutiveCheckpoints,
423:             boolean retainCheckpoints)
424:             throws Exception {
425:         JobGraph initialJobGraph =
426:                 getJobGraph(
427:                         backend,
428:                         externalCheckpoint,
429:                         recoveryClaimMode,
430:                         jobConfig,
431:                         retainCheckpoints);
432:         NotifyingInfiniteTupleSource.countDownLatch = new CountDownLatch(PARALLELISM);
433:         cluster.getClusterClient().submitJob(initialJobGraph).get();
434: 
435:         // wait until all sources have been started
436:         NotifyingInfiniteTupleSource.countDownLatch.await();
437: 
438:         waitForCheckpoint(
439:                 initialJobGraph.getJobID(), cluster.getMiniCluster(), consecutiveCheckpoints);
440:         cluster.getClusterClient().cancel(initialJobGraph.getJobID()).get();
441:         waitUntilJobCanceled(initialJobGraph.getJobID(), cluster.getClusterClient());
442: 
443:         return getLatestCompletedCheckpointPath(
444:                         initialJobGraph.getJobID(), cluster.getMiniCluster())
445:                 .<IllegalStateException>orElseThrow(
446:                         () -> {
447:                             throw new IllegalStateException("Checkpoint not generated");
448:                         });
449:     }
450: 
451:     private static JobGraph getJobGraph(
452:             StateBackend backend,
453:             @Nullable String externalCheckpoint,
454:             RecoveryClaimMode recoveryClaimMode,
455:             Configuration jobConfig,
456:             boolean retainCheckpoints) {
457:         final StreamExecutionEnvironment env =
458:                 StreamExecutionEnvironment.getExecutionEnvironment(jobConfig);
459: 
460:         env.enableCheckpointing(500);
461:         env.setStateBackend(backend);
462:         env.setParallelism(PARALLELISM);
463:         env.getCheckpointConfig()
464:                 .setExternalizedCheckpointRetention(
465:                         retainCheckpoints
466:                                 ? ExternalizedCheckpointRetention.RETAIN_ON_CANCELLATION
467:                                 : ExternalizedCheckpointRetention.DELETE_ON_CANCELLATION);
468:         RestartStrategyUtils.configureNoRestartStrategy(env);
469: 
470:         env.addSource(new NotifyingInfiniteTupleSource(10_000))
471:                 .assignTimestampsAndWatermarks(IngestionTimeWatermarkStrategy.create())
472:                 .keyBy(0)
473:                 .window(TumblingEventTimeWindows.of(Time.seconds(3)))
474:                 .reduce((value1, value2) -> Tuple2.of(value1.f0, value1.f1 + value2.f1))
475:                 .filter(value -> value.f0.startsWith("Tuple 0"));
476: 
477:         StreamGraph streamGraph = env.getStreamGraph();
478: 
479:         JobGraph jobGraph = streamGraph.getJobGraph();
480: 
481:         // recover from previous iteration?
482:         if (externalCheckpoint != null) {
483:             jobGraph.setSavepointRestoreSettings(
484:                     SavepointRestoreSettings.forPath(externalCheckpoint, false, recoveryClaimMode));
485:         }
486: 
487:         return jobGraph;
488:     }
