64: 
65:     private final RescalingController sufficientResourcesController;
66:     private final RescalingController desiredResourcesController;
67:     private final RescaleManager rescaleManager;
68:     private final int rescaleOnFailedCheckpointCount;
69:     // null indicates that there was no change event observed, yet
