224:     /**
225:      * Collects data from a parquet page and returns the final row index where it stopped. The
226:      * returned index can be equal to or less than total.
227:      *
228:      * @param total maximum number of rows to collect
229:      * @param lcv column vector to do initial setup in data collection time
230:      * @param valueList collection of values that will be fed into the vector later
231:      * @param type the element type of array
232:      * @return int
233:      */
234:     private int collectDataFromParquetPage(
235:             int total, HeapArrayVector lcv, List<Object> valueList, LogicalType type) {
236:         int index = 0;
237:         /*
238:          * Here is a nested loop for collecting all values from a parquet page.
239:          * A column of array type can be considered as a list of lists, so the two loops are as below:
240:          * 1. The outer loop iterates on rows (index is a row index, so points to a row in the batch), e.g.:
241:          * [0, 2, 3]    <- index: 0
242:          * [NULL, 3, 4] <- index: 1
243:          *
244:          * 2. The inner loop iterates on values within a row (sets all data from parquet data page
245:          * for an element in ListColumnVector), so fetchNextValue returns values one-by-one:
246:          * 0, 2, 3, NULL, 3, 4
247:          *
248:          * As described below, the repetition level (repetitionLevel != 0)
249:          * can be used to decide when we'll start to read values for the next list.
250:          */
251:         while (!eof && index < total) {
252:             // add element to ListColumnVector one by one
253:             lcv.getOffsets()[index] = valueList.size();
254:             /*
255:              * Let's collect all values for a single list.
256:              * Repetition level = 0 means that a new list started there in the parquet page,
257:              * in that case, let's exit from the loop, and start to collect value for a new list.
258:              */
259:             do {
260:                 /*
261:                  * Definition level = 0 when a NULL value was returned instead of a list
262:                  * (this is not the same as a NULL value in of a list).
263:                  */
264:                 if (definitionLevel == 0) {
265:                     lcv.setNullAt(index);
266:                 }
267:                 valueList.add(
268:                         isCurrentPageDictionaryEncoded
269:                                 ? dictionaryDecodeValue(type, (Integer) lastValue)
270:                                 : lastValue);
271:             } while (fetchNextValue(type) && (repetitionLevel != 0));
272: 
273:             lcv.getLengths()[index] = valueList.size() - lcv.getOffsets()[index];
274:             index++;
275:         }
276:         return index;
277:     }
