400:     /**
401:      * Creates a {@link RowTypeInfo} with projected fields.
402:      *
403:      * @param rowType The original RowTypeInfo whose fields are projected
404:      * @param fieldMapping The field mapping of the projection
405:      * @return A RowTypeInfo with projected fields.
406:      */
407:     public static RowTypeInfo projectFields(RowTypeInfo rowType, int[] fieldMapping) {
408:         TypeInformation[] fieldTypes = new TypeInformation[fieldMapping.length];
409:         String[] fieldNames = new String[fieldMapping.length];
410:         for (int i = 0; i < fieldMapping.length; i++) {
411:             fieldTypes[i] = rowType.getTypeAt(fieldMapping[i]);
412:             fieldNames[i] = rowType.getFieldNames()[fieldMapping[i]];
413:         }
414:         return new RowTypeInfo(fieldTypes, fieldNames);
415:     }
